// Verus specifications for the meshgrid function
#[verus::spec]
fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    // Precondition: x and y must be non-empty vectors
    // Requires: |x| >= 0 && |y| >= 0
    // Ensures: The output matrices have the correct dimensions and values
    // Ensures: |result.0| == |y| && |result.0[0]| == |x| && 
    //          |result.1| == |y| && |result.1[0]| == |x|
    // Invariant: For each row i in the output x_grid, x_grid[i] == x
    // Invariant: For each row j in the output y_grid, y_grid[j] == y
    // Decreases: |y| (the length of the y vector)
    let rows = y.len();
    let cols = x.len();

    // Create the first output matrix filled with the values from x
    let x_grid = vec![x.clone(); rows];

    // Create the second output matrix filled with the values from y
    let y_grid: Vec<Vec<f32>> = y.iter()
        .map(|&value| vec![value; cols])
        .collect();

    (x_grid, y_grid)
}

fn main() {
    let x = vec![1.0, 2.0, 3.0];
    let y = vec![4.0, 5.0];

    let (x_grid, y_grid) = meshgrid(x, y);

    println!("X Grid: {:?}", x_grid);
    println!("Y Grid: {:?}", y_grid);
}